-- table: consumer_checkpoint
CREATE TABLE `consumer_checkpoint` (
  `consumer_checkpoint_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `consumer_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_name` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `partition_key` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `last_contiguous_position` bigint unsigned NOT NULL DEFAULT '0',
  `high_watermark_position` bigint unsigned NOT NULL DEFAULT '0',
  `state_generation` bigint unsigned NOT NULL DEFAULT '0',
  `checkpoint_transition_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `gap_status` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `gap_from_position` bigint unsigned DEFAULT NULL,
  `gap_to_position` bigint unsigned DEFAULT NULL,
  `gap_reason_code` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `blocked_receipt_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `handler_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin DEFAULT NULL,
  `last_receipt_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`consumer_checkpoint_id`),
  UNIQUE KEY `uk_consumer_checkpoint_partition` (`consumer_name`,`source_name`,`partition_key`),
  KEY `idx_consumer_checkpoint_gap` (`gap_status`,`updated_at`),
  KEY `idx_checkpoint_dispatch` (`gap_status`,`consumer_name`,`source_name`,`partition_key`),
  KEY `idx_checkpoint_handler` (`handler_version`,`gap_status`,`updated_at`),
  KEY `idx_checkpoint_transition` (`checkpoint_transition_id`,`consumer_checkpoint_id`),
  CONSTRAINT `chk_checkpoint_gap_shape` CHECK ((((`gap_status` = _utf8mb4'CLEAR') and (`gap_from_position` is null) and (`gap_to_position` is null) and (`gap_reason_code` is null) and (`blocked_receipt_id` is null)) or ((`gap_status` = _utf8mb4'MISSING') and (`gap_from_position` is not null) and (`gap_to_position` is not null) and (`gap_from_position` = (`last_contiguous_position` + 1)) and (`gap_from_position` <= `gap_to_position`) and (`gap_to_position` <= `high_watermark_position`) and (`gap_reason_code` is not null) and (`blocked_receipt_id` is null)) or ((`gap_status` = _utf8mb4'BLOCKED_DEAD_LETTER') and (`gap_from_position` is not null) and (`gap_to_position` is not null) and (`gap_from_position` = (`last_contiguous_position` + 1)) and (`gap_to_position` = `gap_from_position`) and (`gap_to_position` <= `high_watermark_position`) and (`gap_reason_code` is not null) and (`blocked_receipt_id` is not null)) or ((`gap_status` = _utf8mb4'REVIEW_REQUIRED') and (`gap_from_position` is not null) and (`gap_to_position` is not null) and (`gap_from_position` = (`last_contiguous_position` + 1)) and (`gap_from_position` <= `gap_to_position`) and (`gap_to_position` <= `high_watermark_position`) and (`gap_reason_code` is not null)))),
  CONSTRAINT `chk_checkpoint_last_receipt_shape` CHECK ((((`last_contiguous_position` = 0) and (`last_event_id` is null) and (`last_receipt_id` is null)) or ((`last_contiguous_position` > 0) and (`last_event_id` is not null) and (`last_receipt_id` is not null)))),
  CONSTRAINT `chk_checkpoint_position_order` CHECK ((`last_contiguous_position` <= `high_watermark_position`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: event_dead_letter
