  CONSTRAINT `chk_inbox_attempt_bounds` CHECK (((`max_attempts` >= 1) and (`attempt_count` <= `max_attempts`))),
  CONSTRAINT `chk_inbox_completion_shape` CHECK ((((`status` = _ascii'SUCCEEDED') and (`completed_at` is not null) and (`result_json` is not null) and (`result_digest` is not null) and (`completion_manifest_digest` is not null) and (`inbox_transition_id` is not null)) or ((`status` <> _ascii'SUCCEEDED') and (`completed_at` is null) and (`result_json` is null) and (`result_digest` is null) and (`completion_manifest_digest` is null)))),
  CONSTRAINT `chk_inbox_dead_letter_shape` CHECK ((((`status` = _ascii'DEAD_LETTER') and (`dead_lettered_at` is not null) and (`inbox_transition_id` is not null)) or ((`status` <> _ascii'DEAD_LETTER') and (`dead_lettered_at` is null)))),
  CONSTRAINT `chk_inbox_handler_descriptor_digest_lower_hex` CHECK (regexp_like(`handler_descriptor_digest`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_inbox_handler_id_supported` CHECK (regexp_like(`handler_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._:-]{0,95}$')),
  CONSTRAINT `chk_inbox_handler_registration_digest_lower_hex` CHECK (regexp_like(`handler_registration_digest`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_inbox_handler_registry_version_positive` CHECK ((`handler_registry_version` >= 1)),
  CONSTRAINT `chk_inbox_handler_source_digest_lower_hex` CHECK (regexp_like(`handler_source_digest`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_inbox_lease_shape` CHECK ((((`status` = _ascii'CLAIMED') and (`lease_owner` is not null) and (`lease_expires_at` is not null) and (`inbox_transition_id` is not null)) or ((`status` <> _ascii'CLAIMED') and (`lease_owner` is null) and (`lease_expires_at` is null)))),
  CONSTRAINT `chk_inbox_partition_position_positive` CHECK ((`partition_position` >= 1)),
  CONSTRAINT `chk_inbox_payload_protection_metadata` CHECK (((`payload_codec_version` = _ascii'A256GCM:v1') and (`payload_digest_scheme` = _ascii'hmac-sha256:v1') and regexp_like(`payload_key_id`,_ascii'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$') and regexp_like(`payload_digest`,_ascii'^[0-9a-f]{64}$') and (json_type(`payload_json`) = _utf8mb4'OBJECT') and (json_length(`payload_json`) = 10) and (json_contains_path(`payload_json`,_utf8mb4'all',_utf8mb4'$.bindingDigest',_utf8mb4'$.ciphertext',_utf8mb4'$.codecVersion',_utf8mb4'$.contentDigest',_utf8mb4'$.digestScheme',_utf8mb4'$.iv',_utf8mb4'$.keyId',_utf8mb4'$.protection',_utf8mb4'$.purpose',_utf8mb4'$.tag') = 1) and (json_unquote(json_extract(`payload_json`,_utf8mb4'$.protection')) = _utf8mb4'A256GCM') and (json_unquote(json_extract(`payload_json`,_utf8mb4'$.codecVersion')) = `payload_codec_version`) and (json_unquote(json_extract(`payload_json`,_utf8mb4'$.keyId')) = `payload_key_id`) and (json_unquote(json_extract(`payload_json`,_utf8mb4'$.digestScheme')) = `payload_digest_scheme`) and (json_unquote(json_extract(`payload_json`,_utf8mb4'$.contentDigest')) = `payload_digest`) and (json_unquote(json_extract(`payload_json`,_utf8mb4'$.purpose')) = _utf8mb4'PAYLOAD') and regexp_like(json_unquote(json_extract(`payload_json`,_utf8mb4'$.bindingDigest')),_utf8mb4'^[0-9a-f]{64}$') and (json_type(json_extract(`payload_json`,_utf8mb4'$.ciphertext')) = _utf8mb4'STRING') and (json_type(json_extract(`payload_json`,_utf8mb4'$.iv')) = _utf8mb4'STRING') and (json_type(json_extract(`payload_json`,_utf8mb4'$.tag')) = _utf8mb4'STRING'))),
  CONSTRAINT `chk_inbox_receipt_status_supported` CHECK ((`status` in (_ascii'RECEIVED',_ascii'CLAIMED',_ascii'RETRY_PENDING',_ascii'SUCCEEDED',_ascii'DEAD_LETTER',_ascii'REVIEW_REQUIRED'))),
  CONSTRAINT `chk_inbox_result_protection_metadata` CHECK ((((`status` = _ascii'SUCCEEDED') and (`result_codec_version` = _ascii'A256GCM:v1') and (`result_digest_scheme` = _ascii'hmac-sha256:v1') and (`completion_manifest_digest_scheme` = _ascii'hmac-sha256:v1') and regexp_like(`result_key_id`,_ascii'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$') and regexp_like(`result_digest`,_ascii'^[0-9a-f]{64}$') and regexp_like(`completion_manifest_digest`,_ascii'^[0-9a-f]{64}$') and (json_type(`result_json`) = _utf8mb4'OBJECT') and (json_length(`result_json`) = 10) and (json_contains_path(`result_json`,_utf8mb4'all',_utf8mb4'$.bindingDigest',_utf8mb4'$.ciphertext',_utf8mb4'$.codecVersion',_utf8mb4'$.contentDigest',_utf8mb4'$.digestScheme',_utf8mb4'$.iv',_utf8mb4'$.keyId',_utf8mb4'$.protection',_utf8mb4'$.purpose',_utf8mb4'$.tag') = 1) and (json_unquote(json_extract(`result_json`,_utf8mb4'$.protection')) = _utf8mb4'A256GCM') and (json_unquote(json_extract(`result_json`,_utf8mb4'$.codecVersion')) = `result_codec_version`) and (json_unquote(json_extract(`result_json`,_utf8mb4'$.keyId')) = `result_key_id`) and (json_unquote(json_extract(`result_json`,_utf8mb4'$.digestScheme')) = `result_digest_scheme`) and (json_unquote(json_extract(`result_json`,_utf8mb4'$.contentDigest')) = `result_digest`) and (json_unquote(json_extract(`result_json`,_utf8mb4'$.purpose')) = _utf8mb4'RESULT') and regexp_like(json_unquote(json_extract(`result_json`,_utf8mb4'$.bindingDigest')),_utf8mb4'^[0-9a-f]{64}$') and (json_type(json_extract(`result_json`,_utf8mb4'$.ciphertext')) = _utf8mb4'STRING') and (json_type(json_extract(`result_json`,_utf8mb4'$.iv')) = _utf8mb4'STRING') and (json_type(json_extract(`result_json`,_utf8mb4'$.tag')) = _utf8mb4'STRING')) or ((`status` <> _ascii'SUCCEEDED') and (`result_codec_version` is null) and (`result_key_id` is null) and (`result_digest_scheme` is null) and (`completion_manifest_digest_scheme` is null)))),
  CONSTRAINT `chk_inbox_retry_shape` CHECK ((((`status` = _ascii'RETRY_PENDING') and (`next_retry_at` is not null)) or ((`status` <> _ascii'RETRY_PENDING') and (`next_retry_at` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: inbox_replay_run
CREATE TABLE `inbox_replay_run` (
  `replay_run_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `replay_mode` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason_code` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
