  `policy_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `consumer_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_name` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `event_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `schema_version` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `aggregate_type` varchar(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_receipt_status` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_handler_id` varchar(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_handler_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_handler_registry_version` int unsigned NOT NULL,
  `source_handler_descriptor_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_handler_source_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_handler_registration_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `execution_consumer_name` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `execution_handler_id` varchar(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `execution_handler_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `execution_executor_registry_version` int unsigned DEFAULT NULL,
  `execution_executor_registry_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `execution_executor_descriptor_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `execution_executor_source_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `execution_executor_registration_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `target_projection_policy` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `shadow_generation` bigint unsigned DEFAULT NULL,
  `cursor_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `selection_query_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `selection_query_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `selection_after_first_received_at` datetime(3) DEFAULT NULL,
  `selection_after_receipt_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `selection_through_first_received_at` datetime(3) NOT NULL,
  `selection_through_receipt_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `selection_snapshot_at` datetime(3) NOT NULL,
  `selection_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `maximum_selected_count` int unsigned NOT NULL,
  `selected_receipt_count` bigint unsigned NOT NULL,
  `requested_by_actor_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
