  `authorized_by_actor_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `authorized_at` datetime(3) NOT NULL,
  `authorization_ticket_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `maximum_authorization_ttl_seconds` int unsigned NOT NULL,
  `authorization_expires_at` datetime(3) NOT NULL,
  `lease_owner` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `lease_generation` bigint unsigned NOT NULL DEFAULT '0',
  `replay_transition_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `processed_receipt_count` bigint unsigned NOT NULL DEFAULT '0',
  `verified_receipt_count` bigint unsigned NOT NULL DEFAULT '0',
  `shadow_inserted_count` bigint unsigned NOT NULL DEFAULT '0',
  `shadow_replayed_count` bigint unsigned NOT NULL DEFAULT '0',
  `failed_receipt_count` bigint unsigned NOT NULL DEFAULT '0',
  `result_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `last_error_code` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `started_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`replay_run_id`),
  UNIQUE KEY `uk_inbox_replay_execution_consumer` (`execution_consumer_name`),
  UNIQUE KEY `uk_inbox_replay_scope_generation` (`consumer_name`,`source_name`,`source_handler_id`,`shadow_generation`),
  UNIQUE KEY `uk_inbox_replay_run_generation` (`replay_run_id`,`shadow_generation`),
  KEY `idx_inbox_replay_dispatch` (`status`,`authorization_expires_at`,`replay_run_id`),
  KEY `idx_inbox_replay_lease_recovery` (`status`,`lease_expires_at`,`lease_generation`,`replay_run_id`),
  KEY `idx_inbox_replay_selection` (`consumer_name`,`source_name`,`event_type`,`selection_through_first_received_at`,`selection_through_receipt_id`),
  KEY `idx_inbox_replay_approval_inventory` (`requested_by_actor_id`,`authorized_by_actor_id`,`authorized_at`),
  CONSTRAINT `chk_inbox_replay_authorization_ttl` CHECK (((`maximum_authorization_ttl_seconds` = 3600) and (`authorization_expires_at` >= (`authorized_at` + interval 60 second)) and (`authorization_expires_at` <= (`authorized_at` + interval `maximum_authorization_ttl_seconds` second)))),
  CONSTRAINT `chk_inbox_replay_count_bounds` CHECK (((`processed_receipt_count` <= `selected_receipt_count`) and ((`verified_receipt_count` + `failed_receipt_count`) = `processed_receipt_count`) and (((`replay_mode` = _ascii'VERIFY_ONLY') and (`shadow_inserted_count` = 0) and (`shadow_replayed_count` = 0)) or ((`replay_mode` = _ascii'SHADOW_REBUILD') and ((`shadow_inserted_count` + `shadow_replayed_count`) = `verified_receipt_count`))))),
  CONSTRAINT `chk_inbox_replay_cursor_contract` CHECK (((`cursor_version` = _ascii'FIRST_RECEIVED_AT_RECEIPT_ID_V1') and (((`selection_after_first_received_at` is null) and (`selection_after_receipt_id` is null)) or ((`selection_after_first_received_at` is not null) and (`selection_after_receipt_id` is not null) and ((`selection_after_first_received_at` < `selection_through_first_received_at`) or ((`selection_after_first_received_at` = `selection_through_first_received_at`) and (`selection_after_receipt_id` < `selection_through_receipt_id`))))))),
  CONSTRAINT `chk_inbox_replay_executor_identity` CHECK ((((`replay_mode` = _utf8mb4'VERIFY_ONLY') and (`execution_executor_registry_version` is null) and (`execution_executor_registry_digest` is null) and (`execution_executor_descriptor_digest` is null) and (`execution_executor_source_digest` is null) and (`execution_executor_registration_digest` is null)) or ((`replay_mode` = _utf8mb4'SHADOW_REBUILD') and (`execution_executor_registry_version` = 1) and (`execution_executor_registry_digest` = _utf8mb4'9e4ebb37cb7cb07c5c51308826ca0ab50647255a9097c78f136868b67788802f') and (`execution_executor_descriptor_digest` = _utf8mb4'b6bed52a15aacf6bc75e3ea6fc1aa2ad7b5a2c61ab017f27b11f0b971034e0f3') and (`execution_executor_source_digest` = _utf8mb4'344558609a1315f3b259766002ab777ce1c3bcdcca8d1d37db0f4ca0ef460046') and (`execution_executor_registration_digest` = _utf8mb4'c73ffac6b513505bf17b88ae073c9ff5c19d5c5ec63dcf9032c0a8b9b4a60cb7')))),
  CONSTRAINT `chk_inbox_replay_handler_identity` CHECK (((`source_handler_id` = _ascii'task-share-completion-projection-v1') and (`source_handler_version` = _ascii'task-share-completion-v1') and (`source_handler_registry_version` = 1) and regexp_like(`source_handler_descriptor_digest`,_ascii'^[0-9a-f]{64}$') and regexp_like(`source_handler_source_digest`,_ascii'^[0-9a-f]{64}$') and regexp_like(`source_handler_registration_digest`,_ascii'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_inbox_replay_mode_generation` CHECK ((((`replay_mode` = _ascii'VERIFY_ONLY') and (`policy_id` = _ascii'TASK_SHARE_VERIFY_V1') and (`execution_handler_id` = _ascii'task-share-completion-verify-v1') and (`execution_handler_version` = _ascii'task-share-verify-v1') and regexp_like(`execution_consumer_name`,_ascii'^task-share-verify-v1:[0-9a-f]{32}$') and (`target_projection_policy` = _ascii'PRODUCTION_GENERATION_1_READ_ONLY') and (`shadow_generation` is null)) or ((`replay_mode` = _ascii'SHADOW_REBUILD') and (`policy_id` = _ascii'TASK_SHARE_SHADOW_REBUILD_V1') and (`execution_handler_id` = _ascii'task-share-completion-shadow-v1') and (`execution_handler_version` = _ascii'task-share-shadow-v1') and regexp_like(`execution_consumer_name`,_ascii'^task-share-shadow-rebuild-v1:[0-9a-f]{32}$') and (`target_projection_policy` = _ascii'SHADOW_GENERATION_GE_2') and (`shadow_generation` >= 2)))),
  CONSTRAINT `chk_inbox_replay_mode_supported` CHECK ((`replay_mode` in (_ascii'VERIFY_ONLY',_ascii'SHADOW_REBUILD'))),
  CONSTRAINT `chk_inbox_replay_policy_identity` CHECK (((`policy_registry_version` = 1) and regexp_like(`policy_registry_digest`,_ascii'^[0-9a-f]{64}$') and (`policy_id` in (_ascii'TASK_SHARE_SHADOW_REBUILD_V1',_ascii'TASK_SHARE_VERIFY_V1')) and (`policy_version` = 1) and regexp_like(`policy_digest`,_ascii'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_inbox_replay_reason_supported` CHECK ((((`policy_id` = _ascii'TASK_SHARE_VERIFY_V1') and (`reason_code` in (_ascii'INCIDENT_VERIFICATION',_ascii'MIGRATION_PARITY_REVIEW'))) or ((`policy_id` = _ascii'TASK_SHARE_SHADOW_REBUILD_V1') and (`reason_code` in (_ascii'HANDLER_UPGRADE_VALIDATION',_ascii'MIGRATION_PARITY_REVIEW'))))),
  CONSTRAINT `chk_inbox_replay_selection_query` CHECK (((`cursor_version` = _ascii'FIRST_RECEIVED_AT_RECEIPT_ID_V1') and (`selection_query_id` = _ascii'task_share_succeeded_receipts_by_received_at_v1') and regexp_like(`selection_query_digest`,_ascii'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_inbox_replay_selection_sealed` CHECK ((regexp_like(`selection_digest`,_ascii'^[0-9a-f]{64}$') and (`maximum_selected_count` = 10000) and (`selected_receipt_count` between 1 and `maximum_selected_count`) and (`authorized_at` <= `selection_snapshot_at`) and (`selection_snapshot_at` < `authorization_expires_at`))),
  CONSTRAINT `chk_inbox_replay_source_contract` CHECK (((`consumer_name` = _utf8mb4'task-share-completion-projection') and (`source_name` = _utf8mb4'myroot-api') and (`event_type` = _utf8mb4'task.event.recorded.v1') and (`schema_version` = _ascii'1') and (`aggregate_type` = _utf8mb4'TASK_EVENT') and (`source_receipt_status` = _ascii'SUCCEEDED'))),
  CONSTRAINT `chk_inbox_replay_state_shape` CHECK ((((`status` = _ascii'APPROVED') and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` = 0) and (`replay_transition_id` is null) and (`processed_receipt_count` = 0) and (`started_at` is null) and (`completed_at` is null) and (`result_digest` is null) and (`last_error_code` is null)) or ((`status` = _ascii'RUNNING') and (`lease_owner` is not null) and (`lease_expires_at` is not null) and (`lease_generation` >= 1) and (`replay_transition_id` is not null) and (`started_at` is not null) and (`completed_at` is null) and (`result_digest` is null) and (`last_error_code` is null)) or ((`status` = _ascii'SUCCEEDED') and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` >= 1) and (`replay_transition_id` is not null) and (`processed_receipt_count` = `selected_receipt_count`) and (`verified_receipt_count` = `selected_receipt_count`) and (`failed_receipt_count` = 0) and regexp_like(`result_digest`,_ascii'^[0-9a-f]{64}$') and (`last_error_code` is null) and (`started_at` is not null) and (`completed_at` is not null)) or ((`status` in (_ascii'FAILED',_ascii'REVIEW_REQUIRED')) and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` >= 1) and (`replay_transition_id` is not null) and (`result_digest` is null) and (`last_error_code` is not null) and (`started_at` is not null) and (`completed_at` is not null)) or ((`status` = _ascii'EXPIRED') and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` = 0) and (`replay_transition_id` is null) and (`processed_receipt_count` = 0) and (`result_digest` is null) and (`last_error_code` = _ascii'AUTHORIZATION_EXPIRED') and (`started_at` is null) and (`completed_at` is not null)))),
  CONSTRAINT `chk_inbox_replay_status_supported` CHECK ((`status` in (_ascii'APPROVED',_ascii'RUNNING',_ascii'SUCCEEDED',_ascii'FAILED',_ascii'EXPIRED',_ascii'REVIEW_REQUIRED'))),
  CONSTRAINT `chk_inbox_replay_two_person_authorization` CHECK (((`requested_by_actor_id` <> `authorized_by_actor_id`) and (`requested_at` <= `authorized_at`) and regexp_like(`authorization_ticket_digest`,_ascii'^[0-9a-f]{64}$')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: manual_review_item
CREATE TABLE `manual_review_item` (
  `manual_review_item_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `root_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `campaign_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metadata` json DEFAULT NULL,
  `idempotency_key` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `operator_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolved_at` datetime(3) DEFAULT NULL,
  `resolution` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`manual_review_item_id`),
  UNIQUE KEY `uk_manual_review_idempotency` (`idempotency_key`),
  KEY `idx_manual_review_status_priority` (`status`,`priority`,`created_at`),
  KEY `idx_manual_review_user_campaign` (`root_user_id`,`campaign_id`),
  KEY `idx_manual_review_source_scope` (`source_type`,`root_user_id`,`campaign_id`,`created_at`,`manual_review_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: migration_contract_registry
