  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`contract_id`,`contract_version`),
  UNIQUE KEY `uk_migration_contract_identity` (`contract_id`,`contract_version`,`contract_digest`),
  CONSTRAINT `chk_migration_contract_digest_shape` CHECK ((regexp_like(`registry_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`source_query_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`source_adapter_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`target_adapter_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`parity_adapter_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`contract_digest`,_utf8mb4'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_migration_contract_registered_scope` CHECK (((`contract_id` = _utf8mb4'TASK_SHARE_SYNTHETIC_V1') and (`contract_version` = 1) and (`registry_version` = 1) and (`fact_type` = _utf8mb4'TASK_SHARE') and (`authoritative_source` = _utf8mb4'LEGACY_TASK_EVENT') and (`source_type` = _utf8mb4'LEGACY_TASK_EVENT') and (`source_query_id` = _utf8mb4'task_share_legacy_succeeded_by_occurred_at_v1') and (`source_adapter_id` = _utf8mb4'task-share-legacy-source-reader-v1') and (`target_type` = _utf8mb4'TASK_SHARE_MIGRATION_PROJECTION') and (`target_schema_version` = _utf8mb4'TASK_SHARE_MIGRATION_V1') and (`target_adapter_id` = _utf8mb4'task-share-migration-target-writer-v1') and (`parity_adapter_id` = _utf8mb4'task-share-migration-parity-v1') and (`cursor_type` = _utf8mb4'OCCURRED_AT_TASK_EVENT_ID_V1') and (`inclusive` = 0) and (`maximum_batch_size` = 100) and (`allows_network` = 0) and (`allows_outbox` = 0) and (`status` = _utf8mb4'ACTIVE')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: migration_lineage
CREATE TABLE `migration_lineage` (
