  `reversed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  PRIMARY KEY (`migration_lineage_id`),
  UNIQUE KEY `uk_migration_lineage_sequence` (`lineage_identity`,`event_sequence`),
  UNIQUE KEY `uk_migration_lineage_request` (`migration_run_id`,`batch_id`,`source_id`,`lineage_event_type`,`request_id`),
  UNIQUE KEY `uk_migration_lineage_base` (`base_lineage_identity`),
  KEY `idx_migration_lineage_run_status` (`migration_run_id`,`status`,`cursor_value`,`tie_breaker`),
  KEY `idx_migration_lineage_source_target` (`contract_id`,`source_type`,`source_id`,`target_schema_version`),
  CONSTRAINT `fk_migration_lineage_run` FOREIGN KEY (`migration_run_id`) REFERENCES `migration_run` (`migration_run_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_migration_lineage_checksum_shape` CHECK ((regexp_like(`source_checksum`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`target_checksum`,_utf8mb4'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_migration_lineage_cursor_shape` CHECK (((`cursor_type` = _utf8mb4'OCCURRED_AT_TASK_EVENT_ID_V1') and (`cursor_value` is not null) and (`tie_breaker` is not null) and (`inclusive` = 0))),
  CONSTRAINT `chk_migration_lineage_error_shape` CHECK ((((`status` in (_utf8mb4'CONFLICT',_utf8mb4'QUARANTINED',_utf8mb4'REVIEW_REQUIRED')) and (`error_code` is not null) and (`error_code` in (_utf8mb4'TARGET_CONFLICT',_utf8mb4'TARGET_QUARANTINED',_utf8mb4'PARITY_MISMATCH',_utf8mb4'IDENTITY_DRIFT'))) or ((`status` not in (_utf8mb4'CONFLICT',_utf8mb4'QUARANTINED',_utf8mb4'REVIEW_REQUIRED')) and (`error_code` is null)))),
  CONSTRAINT `chk_migration_lineage_event_type` CHECK ((`lineage_event_type` in (_utf8mb4'MIGRATION',_utf8mb4'APPLY_AFTER_DRY_RUN',_utf8mb4'IDEMPOTENT_RETRY',_utf8mb4'FORWARD_REPLAY',_utf8mb4'CONFLICT',_utf8mb4'QUARANTINE',_utf8mb4'REVERSAL'))),
  CONSTRAINT `chk_migration_lineage_identity_shape` CHECK ((regexp_like(`lineage_identity`,_utf8mb4'^[0-9a-f]{64}$') and (((`lineage_event_type` = _utf8mb4'MIGRATION') and (`base_lineage_identity` = `lineage_identity`) and (`event_sequence` = 1)) or ((`lineage_event_type` <> _utf8mb4'MIGRATION') and (`base_lineage_identity` is null) and (`event_sequence` >= 1))))),
  CONSTRAINT `chk_migration_lineage_status` CHECK ((`status` in (_utf8mb4'MIGRATED',_utf8mb4'IDEMPOTENT',_utf8mb4'DRY_RUN_VERIFIED',_utf8mb4'FORWARD_REPLAYED',_utf8mb4'CONFLICT',_utf8mb4'QUARANTINED',_utf8mb4'REVIEW_REQUIRED',_utf8mb4'REVERSED'))),
  CONSTRAINT `chk_migration_lineage_temporal_shape` CHECK (((((`lineage_event_type` = _utf8mb4'FORWARD_REPLAY') or (`status` = _utf8mb4'FORWARD_REPLAYED')) and (`replayed_at` is not null) and (`reversed_at` is null)) or ((`lineage_event_type` = _utf8mb4'REVERSAL') and (`replayed_at` is null) and (`reversed_at` is not null)) or ((`lineage_event_type` not in (_utf8mb4'FORWARD_REPLAY',_utf8mb4'REVERSAL')) and (`status` <> _utf8mb4'FORWARD_REPLAYED') and (`replayed_at` is null) and (`reversed_at` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: migration_run
CREATE TABLE `migration_run` (
