  `source_adapter_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_adapter_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `parity_adapter_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_schema_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `replay_source_run_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `replay_source_result_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `replay_through_cursor_value` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `replay_through_tie_breaker` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `cursor_type` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `cursor_value` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `cursor_tie_breaker` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `inclusive` tinyint(1) NOT NULL,
  `last_contiguous_cursor_value` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `last_contiguous_tie_breaker` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `lease_owner` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `lease_generation` bigint unsigned NOT NULL DEFAULT '0',
  `transition_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `processed_count` bigint unsigned NOT NULL DEFAULT '0',
  `migrated_count` bigint unsigned NOT NULL DEFAULT '0',
  `idempotent_count` bigint unsigned NOT NULL DEFAULT '0',
  `conflict_count` bigint unsigned NOT NULL DEFAULT '0',
  `quarantined_count` bigint unsigned NOT NULL DEFAULT '0',
  `review_required_count` bigint unsigned NOT NULL DEFAULT '0',
  `batch_count` bigint unsigned NOT NULL DEFAULT '0',
  `result_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `last_error_code` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `opened_at` datetime(3) NOT NULL,
  `verified_at` datetime(3) DEFAULT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`migration_run_id`),
  UNIQUE KEY `uk_migration_run_request` (`contract_id`,`request_id`),
  KEY `idx_migration_run_dispatch` (`status`,`lease_expires_at`,`migration_run_id`),
  KEY `idx_migration_run_snapshot` (`contract_id`,`snapshot_id`,`snapshot_revision`),
  KEY `fk_migration_run_contract` (`contract_id`,`contract_version`,`contract_digest`),
  KEY `idx_migration_run_replay_source` (`replay_source_run_id`),
  CONSTRAINT `fk_migration_run_contract` FOREIGN KEY (`contract_id`, `contract_version`, `contract_digest`) REFERENCES `migration_contract_registry` (`contract_id`, `contract_version`, `contract_digest`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_migration_run_replay_source` FOREIGN KEY (`replay_source_run_id`) REFERENCES `migration_run` (`migration_run_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_migration_run_count_shape` CHECK (((`processed_count` = ((((`migrated_count` + `idempotent_count`) + `conflict_count`) + `quarantined_count`) + `review_required_count`)) and (((`conflict_count` + `quarantined_count`) + `review_required_count`) <= 1))),
  CONSTRAINT `chk_migration_run_cursor_shape` CHECK (((`cursor_type` = _utf8mb4'OCCURRED_AT_TASK_EVENT_ID_V1') and (`inclusive` = 0) and (((`cursor_value` is null) and (`cursor_tie_breaker` is null)) or ((`cursor_value` is not null) and (`cursor_tie_breaker` is not null))) and (((`last_contiguous_cursor_value` is null) and (`last_contiguous_tie_breaker` is null)) or ((`last_contiguous_cursor_value` is not null) and (`last_contiguous_tie_breaker` is not null) and (`last_contiguous_cursor_value` = `cursor_value`) and (`last_contiguous_tie_breaker` = `cursor_tie_breaker`))))),
  CONSTRAINT `chk_migration_run_digest_shape` CHECK ((regexp_like(`registry_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`contract_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`source_query_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`source_adapter_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`target_adapter_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`parity_adapter_digest`,_utf8mb4'^[0-9a-f]{64}$') and ((`result_digest` is null) or regexp_like(`result_digest`,_utf8mb4'^[0-9a-f]{64}$')))),
  CONSTRAINT `chk_migration_run_error_code` CHECK (((`last_error_code` is null) or (`last_error_code` in (_utf8mb4'SOURCE_DRIFT',_utf8mb4'TARGET_CONFLICT',_utf8mb4'TARGET_QUARANTINED',_utf8mb4'PARITY_MISMATCH',_utf8mb4'IDENTITY_DRIFT',_utf8mb4'LEASE_EXPIRED',_utf8mb4'PERSISTENCE_FAILED',_utf8mb4'ACK_UNKNOWN')))),
  CONSTRAINT `chk_migration_run_lease_shape` CHECK ((((`status` = _utf8mb4'RUNNING') and (`lease_owner` is not null) and (`lease_expires_at` is not null) and (`lease_generation` > 0) and (`transition_id` is not null)) or ((`status` <> _utf8mb4'RUNNING') and (`lease_owner` is null) and (`lease_expires_at` is null)))),
  CONSTRAINT `chk_migration_run_mode` CHECK ((`migration_mode` in (_utf8mb4'DRY_RUN',_utf8mb4'APPLY',_utf8mb4'FORWARD_REPLAY'))),
  CONSTRAINT `chk_migration_run_replay_binding` CHECK ((((`migration_mode` = _utf8mb4'FORWARD_REPLAY') and (`replay_source_run_id` is not null) and (`replay_source_result_digest` is not null) and regexp_like(`replay_source_result_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`replay_through_cursor_value` is not null) and (`replay_through_tie_breaker` is not null) and (`cursor_value` is not null) and (`cursor_tie_breaker` is not null) and ((`cursor_value` < `replay_through_cursor_value`) or ((`cursor_value` = `replay_through_cursor_value`) and (`cursor_tie_breaker` <= `replay_through_tie_breaker`)))) or ((`migration_mode` <> _utf8mb4'FORWARD_REPLAY') and (`replay_source_run_id` is null) and (`replay_source_result_digest` is null) and (`replay_through_cursor_value` is null) and (`replay_through_tie_breaker` is null)))),
  CONSTRAINT `chk_migration_run_status` CHECK ((`status` in (_utf8mb4'OPEN',_utf8mb4'RUNNING',_utf8mb4'PARITY_PENDING',_utf8mb4'VERIFIED',_utf8mb4'REVIEW_REQUIRED',_utf8mb4'FAILED',_utf8mb4'ACK_UNKNOWN'))),
  CONSTRAINT `chk_migration_run_terminal_shape` CHECK ((((`status` = _utf8mb4'VERIFIED') and (`verified_at` is not null) and (`completed_at` is not null)) or ((`status` <> _utf8mb4'VERIFIED') and (`verified_at` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

