  CONSTRAINT `chk_notification_job_v1_request_digest` CHECK (regexp_like(`request_digest`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_notification_job_v1_stable_error` CHECK ((((`status` in (_utf8mb4'SCHEDULED',_utf8mb4'SENDING',_utf8mb4'PROVIDER_ACCEPTED',_utf8mb4'CANCELED')) and (`stable_error_code` is null)) or ((`status` = _utf8mb4'SKIPPED') and (`stable_error_code` is not null) and (`stable_error_code` in (_utf8mb4'ALREADY_CHECKED_IN',_utf8mb4'NO_SUBSCRIPTION',_utf8mb4'NO_GRANT'))) or ((`status` = _utf8mb4'FAILED') and (`stable_error_code` is not null) and (`stable_error_code` in (_utf8mb4'WECHAT_NO_GRANT',_utf8mb4'WECHAT_REJECTED',_utf8mb4'PROVIDER_CONFIRMED_NOT_SENT',_utf8mb4'SEND_FAILED',_utf8mb4'WECHAT_SEND_FAILED',_utf8mb4'PROVIDER_REQUEST_INVALID'))) or ((`status` = _utf8mb4'OUTCOME_UNKNOWN') and (`stable_error_code` is not null) and (`stable_error_code` in (_utf8mb4'PROVIDER_RESULT_UNKNOWN',_utf8mb4'HTTP_OUTCOME_UNKNOWN',_utf8mb4'NETWORK_OUTCOME_UNKNOWN',_utf8mb4'NON_JSON_OUTCOME_UNKNOWN'))))),
  CONSTRAINT `chk_notification_job_v1_status` CHECK ((`status` in (_ascii'SCHEDULED',_ascii'SENDING',_ascii'PROVIDER_ACCEPTED',_ascii'SKIPPED',_ascii'FAILED',_ascii'OUTCOME_UNKNOWN',_ascii'CANCELED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

