  `lease_owner` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `lease_generation` bigint unsigned NOT NULL DEFAULT '0',
  `dispatch_transition_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `last_error_json` json DEFAULT NULL,
  `release_id` varchar(96) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `succeeded_at` datetime(3) DEFAULT NULL,
  `dead_lettered_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`outbox_event_id`),
  UNIQUE KEY `uk_outbox_topic_dedupe` (`topic`,`dedupe_key`),
  UNIQUE KEY `uk_outbox_partition_position` (`source_name`,`partition_key`,`partition_position`),
  KEY `idx_outbox_dispatch` (`status`,`available_at`,`lease_expires_at`,`partition_position`),
  KEY `idx_outbox_aggregate_version` (`aggregate_type`,`aggregate_id`,`aggregate_version`),
  KEY `idx_outbox_release` (`release_id`,`created_at`),
  KEY `idx_outbox_lease_owner` (`lease_owner`,`status`,`lease_generation`),
  KEY `idx_outbox_transition` (`dispatch_transition_id`,`outbox_event_id`),
  KEY `idx_outbox_lease_recovery` (`status`,`lease_expires_at`,`outbox_event_id`),
  KEY `idx_outbox_pending_due` (`status`,`retry_policy_version`,`available_at`,`outbox_event_id`),
  KEY `idx_outbox_retry_due` (`status`,`retry_policy_version`,`next_retry_at`,`outbox_event_id`),
  KEY `idx_outbox_partition_head` (`source_name`,`partition_key`,`partition_position`,`status`),
  CONSTRAINT `chk_outbox_partition_position_positive` CHECK ((`partition_position` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

