  KEY `idx_settlement_source_resolution_scope` (`root_user_id`,`campaign_id`,`created_at`,`settlement_source_resolution_audit_id`),
  CONSTRAINT `fk_settlement_source_resolution_authority` FOREIGN KEY (`root_user_id`, `campaign_id`) REFERENCES `settlement_source_authority` (`root_user_id`, `campaign_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_settlement_source_resolution_candidate` FOREIGN KEY (`manual_review_item_id`) REFERENCES `manual_review_item` (`manual_review_item_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
