-- table: task_activity_assignment
CREATE TABLE `task_activity_assignment` (
  `task_activity_assignment_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `root_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_definition_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_definition_version` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `activity_enrollment_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `activity_session_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `initial_status` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_confirmed_event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_confirmed_event_type` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_confirmed_at` datetime(3) NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`task_activity_assignment_id`),
  UNIQUE KEY `uk_task_activity_assignment_source` (`activity_enrollment_id`,`task_definition_id`,`task_definition_version`),
  UNIQUE KEY `uk_task_activity_assignment_confirmed_event` (`source_confirmed_event_id`),
  KEY `idx_task_activity_assignment_user_status` (`root_user_id`,`initial_status`,`updated_at`),
  KEY `idx_task_activity_assignment_session` (`activity_session_id`,`initial_status`),
  KEY `fk_task_activity_assignment_definition` (`task_definition_id`),
  CONSTRAINT `fk_task_activity_assignment_definition` FOREIGN KEY (`task_definition_id`) REFERENCES `task_definition` (`task_definition_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_task_activity_assignment_enrollment` FOREIGN KEY (`activity_enrollment_id`) REFERENCES `activity_enrollment` (`activity_enrollment_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_task_activity_assignment_session` FOREIGN KEY (`activity_session_id`) REFERENCES `activity_session` (`activity_session_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_task_activity_assignment_user` FOREIGN KEY (`root_user_id`) REFERENCES `root_user` (`root_user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_task_activity_assignment_confirmed_contract` CHECK ((`source_confirmed_event_type` = _utf8mb4'activity.enrollment.confirmed.v1')),
  CONSTRAINT `chk_task_activity_assignment_initial_status` CHECK ((`initial_status` = _utf8mb4'AVAILABLE'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: task_definition
