  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `required` tinyint(1) NOT NULL DEFAULT '1',
  `display_order` int NOT NULL DEFAULT '10',
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `config_json` json DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`task_definition_id`),
  KEY `idx_task_definition_campaign_status` (`campaign_id`,`status`,`display_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: task_event
CREATE TABLE `task_event` (
  `task_event_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `root_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `campaign_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_definition_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL,
  `task_date` date NOT NULL,
  `payload_json` json DEFAULT NULL,
  `idempotency_key` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `idempotency_operation` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'RECORD_TASK_EVENT:v1',
  `request_canonical_version` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `request_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `request_digest_scheme` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `request_digest_key_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `occurred_at_client_supplied` tinyint(1) DEFAULT NULL,
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_channel` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `occurred_at` datetime(3) NOT NULL,
  `created_at` datetime(3) NOT NULL,
  PRIMARY KEY (`task_event_id`),
  UNIQUE KEY `uk_task_event_idempotency_scope` (`root_user_id`,`idempotency_operation`,`idempotency_key`),
  KEY `idx_task_event_user_campaign_date` (`root_user_id`,`campaign_id`,`task_date`),
  KEY `idx_task_event_campaign_type_date` (`campaign_id`,`task_type`,`task_date`),
  KEY `idx_task_event_request_digest_crypto` (`request_digest_scheme`,`request_digest_key_id`,`task_event_id`),
  CONSTRAINT `chk_task_event_idempotency_operation` CHECK ((`idempotency_operation` = _utf8mb4'RECORD_TASK_EVENT:v1')),
  CONSTRAINT `chk_task_event_occurred_at_provenance` CHECK (((`occurred_at_client_supplied` is null) or (`occurred_at_client_supplied` in (0,1)))),
  CONSTRAINT `chk_task_event_request_digest_metadata` CHECK ((((`request_canonical_version` is null) and (`request_digest` is null) and (`request_digest_scheme` is null) and (`request_digest_key_id` is null)) or ((`request_canonical_version` is not null) and (`request_digest` is not null) and (`request_digest_scheme` is not null) and (`request_digest_key_id` is not null) and (`request_canonical_version` = _utf8mb4'canonical-json:v1') and regexp_like(`request_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`request_digest_scheme` = _utf8mb4'hmac-sha256:v1') and regexp_like(`request_digest_key_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: task_progress_snapshot
CREATE TABLE `task_progress_snapshot` (
  `task_progress_snapshot_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
