  `computed_at` datetime(3) NOT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`task_progress_snapshot_id`),
  UNIQUE KEY `uk_task_progress_user_campaign` (`root_user_id`,`campaign_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- table: task_share_completion_projection
CREATE TABLE `task_share_completion_projection` (
  `projection_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `projection_generation` tinyint unsigned NOT NULL DEFAULT '1',
  `task_event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_event_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
  `source_event_type` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_schema_version` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
