  CONSTRAINT `chk_task_share_projection_outcome_contract` CHECK (((`task_type` = _utf8mb4'SHARE') and (`completion_event_type` = _utf8mb4'SHARE_COMPLETED'))),
  CONSTRAINT `chk_task_share_projection_registration_digest` CHECK (regexp_like(`handler_registration_digest`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_task_share_projection_source_contract` CHECK (((`source_event_type` = _utf8mb4'task.event.recorded.v1') and (`source_schema_version` = _utf8mb4'1') and (`source_name` = _utf8mb4'myroot-api') and (`source_partition_key` = concat(_utf8mb4'task_event:',`task_event_id`)) and (`source_partition_position` = 1) and (`source_aggregate_version` = 1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

