  CONSTRAINT `chk_task_share_migration_scope` CHECK (((`contract_id` = _utf8mb4'TASK_SHARE_SYNTHETIC_V1') and (`target_schema_version` = _utf8mb4'TASK_SHARE_MIGRATION_V1') and (`task_type` = _utf8mb4'SHARE') and (`completion_event_type` = _utf8mb4'SHARE_COMPLETED')))
