  CONSTRAINT `fk_v1_runtime_alert_cycle` FOREIGN KEY (`runtime_cycle_id`, `environment_id`, `schedule_id`, `input_digest`) REFERENCES `v1_runtime_cycle` (`runtime_cycle_id`, `environment_id`, `schedule_id`, `input_digest`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_v1_runtime_alert_code` CHECK (regexp_like(`alert_code`,_utf8mb4'^[A-Z][A-Z0-9_]{0,63}$')),
  CONSTRAINT `chk_v1_runtime_alert_digest_shape` CHECK ((regexp_like(`runtime_alert_id`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`input_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`dedupe_digest`,_utf8mb4'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_v1_runtime_alert_severity` CHECK ((`severity` in (_utf8mb4'BLOCKER',_utf8mb4'WARNING')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: v1_runtime_alert_delivery
CREATE TABLE `v1_runtime_alert_delivery` (
  `runtime_alert_delivery_id` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `runtime_alert_id` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `environment_id` varchar(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `registration_mode` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_authority_version` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_ref` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_digest_scheme` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_digest_key_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload_schema_version` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload_canonical_version` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload_digest_scheme` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload_digest_key_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `slo_class` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `slo_target_seconds` int unsigned NOT NULL,
  `retry_policy_version` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `maximum_attempts` tinyint unsigned NOT NULL,
  `status` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `attempt_count` tinyint unsigned NOT NULL DEFAULT '0',
  `available_at` datetime(3) NOT NULL,
  `lease_owner` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `lease_generation` bigint unsigned NOT NULL DEFAULT '0',
  `provider_started_at` datetime(3) DEFAULT NULL,
  `provider_completed_at` datetime(3) DEFAULT NULL,
  `receipt_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `receipt_digest_scheme` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `receipt_digest_key_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `stable_error_code` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`runtime_alert_delivery_id`),
  UNIQUE KEY `uk_v1_runtime_alert_delivery_alert_authority` (`runtime_alert_id`),
  KEY `idx_v1_runtime_alert_delivery_due` (`environment_id`,`registration_mode`,`receiver_binding_ref`,`receiver_binding_authority_version`,`status`,`available_at`,`slo_target_seconds`,`runtime_alert_delivery_id`),
  KEY `idx_v1_runtime_alert_delivery_recovery` (`environment_id`,`registration_mode`,`receiver_binding_ref`,`receiver_binding_authority_version`,`status`,`lease_expires_at`,`runtime_alert_delivery_id`),
  KEY `idx_v1_runtime_alert_delivery_crypto` (`receiver_binding_digest_key_id`,`payload_digest_key_id`,`receipt_digest_key_id`,`runtime_alert_delivery_id`),
  CONSTRAINT `fk_v1_runtime_alert_delivery_alert` FOREIGN KEY (`runtime_alert_id`) REFERENCES `v1_runtime_alert` (`runtime_alert_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_v1_runtime_alert_delivery_attempts` CHECK (((`retry_policy_version` = _utf8mb4'pre-provider-exponential:v1') and (`maximum_attempts` between 1 and 5) and (`attempt_count` <= `maximum_attempts`))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_authority` CHECK (((`registration_mode` in (_utf8mb4'DRY_RUN',_utf8mb4'CONTROLLED')) and (`receiver_binding_authority_version` = _utf8mb4'runtime-alert-receiver-authority:v1'))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_error` CHECK ((((`status` in (_utf8mb4'PENDING',_utf8mb4'CLAIMED',_utf8mb4'STARTED',_utf8mb4'DELIVERED')) and (`stable_error_code` is null)) or ((`status` in (_utf8mb4'RETRY_WAIT',_utf8mb4'DEAD_LETTER',_utf8mb4'UNKNOWN')) and (`stable_error_code` is not null) and regexp_like(`stable_error_code`,_utf8mb4'^[A-Z][A-Z0-9_]{0,63}$')))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_identity` CHECK ((regexp_like(`runtime_alert_delivery_id`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`runtime_alert_id`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`receiver_binding_ref`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$') and regexp_like(`receiver_binding_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`receiver_binding_digest_scheme` = _utf8mb4'hmac-sha256:v1') and regexp_like(`receiver_binding_digest_key_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_payload` CHECK (((`payload_schema_version` = _utf8mb4'myroot.runtime-alert.delivery.v1') and (`payload_canonical_version` = _utf8mb4'canonical-json:v1') and regexp_like(`payload_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`payload_digest_scheme` = _utf8mb4'hmac-sha256:v1') and regexp_like(`payload_digest_key_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_receipt` CHECK ((((`status` = _utf8mb4'DELIVERED') and (`receipt_digest` is not null) and regexp_like(`receipt_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`receipt_digest_scheme` is not null) and (`receipt_digest_scheme` = _utf8mb4'hmac-sha256:v1') and (`receipt_digest_key_id` is not null) and regexp_like(`receipt_digest_key_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$')) or ((`status` <> _utf8mb4'DELIVERED') and (`receipt_digest` is null) and (`receipt_digest_scheme` is null) and (`receipt_digest_key_id` is null)))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_slo` CHECK ((((`slo_class` = _utf8mb4'BLOCKER_IMMEDIATE') and (`slo_target_seconds` = 300)) or ((`slo_class` = _utf8mb4'WARNING_STANDARD') and (`slo_target_seconds` = 1800)))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_state` CHECK ((((`status` = _utf8mb4'PENDING') and (`attempt_count` = 0) and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` = 0) and (`provider_started_at` is null) and (`provider_completed_at` is null)) or ((`status` = _utf8mb4'CLAIMED') and (`attempt_count` between 1 and `maximum_attempts`) and (`lease_owner` is not null) and (`lease_expires_at` is not null) and (`lease_generation` >= 1) and (`provider_started_at` is null) and (`provider_completed_at` is null)) or ((`status` = _utf8mb4'RETRY_WAIT') and (`attempt_count` >= 1) and (`attempt_count` < `maximum_attempts`) and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` >= 1) and (`provider_started_at` is null) and (`provider_completed_at` is null)) or ((`status` = _utf8mb4'STARTED') and (`attempt_count` between 1 and `maximum_attempts`) and (`lease_owner` is not null) and (`lease_expires_at` is not null) and (`lease_generation` >= 1) and (`provider_started_at` is not null) and (`provider_started_at` < `lease_expires_at`) and (`provider_completed_at` is null)) or ((`status` = _utf8mb4'DELIVERED') and (`attempt_count` between 1 and `maximum_attempts`) and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` >= 1) and (`provider_started_at` is not null) and (`provider_completed_at` is not null) and (`provider_started_at` <= `provider_completed_at`)) or ((`status` = _utf8mb4'DEAD_LETTER') and (`attempt_count` between 1 and `maximum_attempts`) and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` >= 1) and (`provider_started_at` is null) and (`provider_completed_at` is not null)) or ((`status` = _utf8mb4'UNKNOWN') and (`attempt_count` between 1 and `maximum_attempts`) and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` >= 1) and (`provider_started_at` is not null) and (`provider_completed_at` is not null) and (`provider_started_at` <= `provider_completed_at`)))),
  CONSTRAINT `chk_v1_runtime_alert_delivery_status` CHECK ((`status` in (_utf8mb4'PENDING',_utf8mb4'CLAIMED',_utf8mb4'RETRY_WAIT',_utf8mb4'STARTED',_utf8mb4'DELIVERED',_utf8mb4'DEAD_LETTER',_utf8mb4'UNKNOWN')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: v1_runtime_alert_registration_authority
CREATE TABLE `v1_runtime_alert_registration_authority` (
  `environment_id` varchar(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `authority_generation` bigint unsigned NOT NULL,
  `registration_mode` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_authority_version` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_ref` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_digest_scheme` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `receiver_binding_digest_key_id` varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `activated_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`environment_id`),
  KEY `idx_v1_runtime_alert_registration_authority_status` (`status`,`registration_mode`,`environment_id`),
  KEY `idx_v1_runtime_alert_registration_authority_crypto` (`receiver_binding_digest_key_id`,`environment_id`),
  CONSTRAINT `chk_v1_runtime_alert_registration_authority_binding` CHECK (((`receiver_binding_authority_version` = _utf8mb4'runtime-alert-receiver-authority:v1') and regexp_like(`receiver_binding_ref`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$') and regexp_like(`receiver_binding_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`receiver_binding_digest_scheme` = _utf8mb4'hmac-sha256:v1') and regexp_like(`receiver_binding_digest_key_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'))),
  CONSTRAINT `chk_v1_runtime_alert_registration_authority_generation` CHECK ((`authority_generation` >= 1)),
  CONSTRAINT `chk_v1_runtime_alert_registration_authority_mode` CHECK ((`registration_mode` in (_utf8mb4'DRY_RUN',_utf8mb4'CONTROLLED'))),
  CONSTRAINT `chk_v1_runtime_alert_registration_authority_status` CHECK ((`status` in (_utf8mb4'ACTIVE',_utf8mb4'DISABLED'))),
  CONSTRAINT `chk_v1_runtime_alert_registration_authority_time` CHECK ((`activated_at` <= `updated_at`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: v1_runtime_cycle
CREATE TABLE `v1_runtime_cycle` (
  `runtime_cycle_id` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `environment_id` varchar(96) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `schedule_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `scheduled_at` datetime(3) NOT NULL,
  `input_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `lease_owner` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `lease_expires_at` datetime(3) DEFAULT NULL,
  `lease_generation` bigint unsigned NOT NULL DEFAULT '0',
  `claim_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `finalization_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `result_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `blocker_count` bigint unsigned NOT NULL DEFAULT '0',
  `error_code` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `claimed_at` datetime(3) NOT NULL,
  `completed_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`runtime_cycle_id`),
  UNIQUE KEY `uk_v1_runtime_cycle_schedule` (`environment_id`,`schedule_id`),
  UNIQUE KEY `uk_v1_runtime_cycle_scope_identity` (`runtime_cycle_id`,`environment_id`,`schedule_id`,`input_digest`),
  KEY `idx_v1_runtime_cycle_recovery` (`environment_id`,`status`,`lease_expires_at`,`runtime_cycle_id`),
  KEY `idx_v1_runtime_cycle_attestation` (`environment_id`,`status`,`completed_at`,`runtime_cycle_id`),
  CONSTRAINT `chk_v1_runtime_cycle_digest_shape` CHECK ((regexp_like(`runtime_cycle_id`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`input_digest`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`claim_digest`,_utf8mb4'^[0-9a-f]{64}$') and ((`finalization_digest` is null) or regexp_like(`finalization_digest`,_utf8mb4'^[0-9a-f]{64}$')) and ((`result_digest` is null) or regexp_like(`result_digest`,_utf8mb4'^[0-9a-f]{64}$')))),
  CONSTRAINT `chk_v1_runtime_cycle_error_code` CHECK (((`error_code` is null) or regexp_like(`error_code`,_utf8mb4'^[A-Z][A-Z0-9_]{0,63}$'))),
  CONSTRAINT `chk_v1_runtime_cycle_state_shape` CHECK ((((`status` = _utf8mb4'RUNNING') and (`lease_owner` is not null) and (`lease_expires_at` is not null) and (`lease_generation` > 0) and (`finalization_digest` is null) and (`result_digest` is null) and (`blocker_count` = 0) and (`error_code` is null) and (`completed_at` is null)) or ((`status` <> _utf8mb4'RUNNING') and (`lease_owner` is null) and (`lease_expires_at` is null) and (`lease_generation` > 0) and (`finalization_digest` is not null) and (`result_digest` is not null) and (`completed_at` is not null) and (((`status` = _utf8mb4'SUCCEEDED') and (`blocker_count` = 0) and (`error_code` is null)) or ((`status` = _utf8mb4'SKIPPED_BUSY') and (`blocker_count` = 0) and (`error_code` is not null)) or ((`status` in (_utf8mb4'FAILED_PRECONDITION',_utf8mb4'REVIEW_REQUIRED')) and (`blocker_count` > 0) and (`error_code` is not null)))))),
  CONSTRAINT `chk_v1_runtime_cycle_status` CHECK ((`status` in (_utf8mb4'RUNNING',_utf8mb4'SUCCEEDED',_utf8mb4'SKIPPED_BUSY',_utf8mb4'FAILED_PRECONDITION',_utf8mb4'REVIEW_REQUIRED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- table: wechat_identity
CREATE TABLE `wechat_identity` (
  `wechat_identity_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `root_user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `app_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `openid` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unionid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unionid_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unionid_trust_status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'UNVERIFIED',
  `unionid_provenance_source` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `unionid_verified_at` datetime(3) DEFAULT NULL,
  `unionid_provenance_canonical_version` varchar(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `unionid_provenance_digest` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `unionid_provenance_digest_scheme` varchar(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `unionid_provenance_key_id` varchar(128) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `created_at` datetime(3) NOT NULL,
  `updated_at` datetime(3) NOT NULL,
  `last_seen_at` datetime(3) NOT NULL,
  PRIMARY KEY (`wechat_identity_id`),
  UNIQUE KEY `uk_wechat_identity_app_openid` (`app_code`,`openid`),
  UNIQUE KEY `uk_wechat_identity_root_app` (`root_user_id`,`app_code`),
  KEY `idx_wechat_identity_root_user` (`root_user_id`),
  KEY `idx_wechat_identity_unionid` (`unionid`),
  KEY `idx_wechat_identity_unionid_authority` (`unionid`,`unionid_trust_status`,`root_user_id`),
  KEY `idx_wechat_identity_provenance_crypto` (`unionid_provenance_digest_scheme`,`unionid_provenance_key_id`,`wechat_identity_id`),
  CONSTRAINT `chk_wechat_identity_unionid_provenance` CHECK ((((`unionid_trust_status` = _utf8mb4'UNVERIFIED') and (`unionid_status` is not null) and (`unionid_status` = _utf8mb4'PENDING') and (`unionid_provenance_source` is null) and (`unionid_verified_at` is null) and (`unionid_provenance_canonical_version` is null) and (`unionid_provenance_digest` is null) and (`unionid_provenance_digest_scheme` is null) and (`unionid_provenance_key_id` is null)) or ((`unionid_trust_status` = _utf8mb4'VERIFIED') and (`unionid` is not null) and (`unionid_status` is not null) and (`unionid_status` = _utf8mb4'LINKED') and (`unionid_provenance_source` is not null) and (`unionid_provenance_source` in (_utf8mb4'CLOUDBASE',_utf8mb4'WECHAT_GATEWAY',_utf8mb4'WECHAT_CODE2SESSION')) and (`unionid_verified_at` is not null) and (`unionid_provenance_canonical_version` is not null) and (`unionid_provenance_canonical_version` = _utf8mb4'canonical-json:v1') and (`unionid_provenance_digest` is not null) and regexp_like(`unionid_provenance_digest`,_utf8mb4'^[0-9a-f]{64}$') and (`unionid_provenance_digest_scheme` is not null) and (`unionid_provenance_digest_scheme` = _utf8mb4'hmac-sha256:v1') and (`unionid_provenance_key_id` is not null) and regexp_like(`unionid_provenance_key_id`,_utf8mb4'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
